compliant.code:
import boto3

cloudwatch = boto3.client('cloudwatch')

# Good: Custom namespace that doesn't start with 'AWS/'
cloudwatch.put_metric_data(
    Namespace='MyApp/Performance',
    MetricData=[
        {
            'MetricName': 'RequestLatency',
            'Value': 123.45,
            'Unit': 'Milliseconds'
        }
    ]
)

noncompliant.code:
import boto3

cloudwatch = boto3.client('cloudwatch')

# Bad: Namespace starts with reserved 'AWS/' prefix
cloudwatch.put_metric_data(
    Namespace='AWS/MyCustomMetrics',
    MetricData=[
        {
            'MetricName': 'CustomMetric',
            'Value': 42,
            'Unit': 'Count'
        }
    ]
)
